	"修改端口或重置令牌后，需要重新复制配置并重启客户端。调用联网、云端模型或本地模型功能时，还需提前配置对应的网络、API Key 或模型环境。": "After changing the port or resetting the token, re-copy the config and restart the client. Using web access, cloud models or local models also requires the corresponding network, API key or model environment to be set up first.",
	"未找到本地 MCP 适配器脚本。": "Local MCP adapter script not found.",
	"软件需保持运行，并开启上方“远程控制会话”。": "Keep the app running and start the \"remote control session\" above.",
	可达的局域网地址: "Reachable LAN address",
	"客户端需能访问这台电脑的局域网 IP 和所选端口；Docker 可使用 host.docker.internal。": "The client must be able to reach this computer's LAN IP and selected port; Docker can use host.docker.internal.",
	"支持 Streamable HTTP": "Streamable HTTP support",
	"客户端需支持 Streamable HTTP MCP，并允许配置 Authorization 请求头。": "The client must support Streamable HTTP MCP and custom Authorization headers.",
	"Bearer Token 鉴权": "Bearer token authentication",
	"每次请求都必须携带本机凭据存储中的 256 位令牌。": "Every request must include the 256-bit token stored in the local credential store.",
	"确认开启远程 MCP": "Confirm remote MCP",
	"确认暴露远程 MCP 服务": "Confirm remote MCP exposure",
	"服务将监听 0.0.0.0，局域网内能够到达该端口的设备都可以尝试连接。": "The service will listen on 0.0.0.0, so any device that can reach the port on your LAN can attempt to connect.",
	"持有 Bearer Token 的客户端按自主模式运行，可无审批执行永久删除、文件写入、配置写入和付费媒体生成。": "Clients holding the Bearer token run autonomously and can permanently delete, write files or settings, and generate paid media without approval.",
	"请确认运行在受信网络、Docker 或其他隔离环境中，并继续保留独立备份。": "Use this only on a trusted network, in Docker, or another isolated environment, and keep independent backups.",
