	" 新端口在下次开启会话时生效。": " 새 포트는 다음 세션 시작 시 적용됩니다.",
	"本页没有当前令牌。停止后重新开启以生成新的客户端配置。": "이 페이지에는 현재 토큰이 없습니다. 중지 후 다시 시작하면 새 클라이언트 설정이 생성됩니다.",
