	复制客户端配置: "클라이언트 설정 복사",
	"粘贴到 Claude Desktop / Cursor 等客户端的 MCP 配置中。会话未开启时客户端调用会报错，重新开启即可继续用同一份配置。": "Claude Desktop / Cursor 등 클라이언트의 MCP 설정에 붙여넣으세요. 세션이 중지된 동안에는 클라이언트 호출이 오류가 나며, 다시 시작하면 같은 설정을 계속 사용할 수 있습니다.",
	"复制前请把 <AI_CANVAS_IP> 替换为运行 AI Canvas 电脑的局域网 IP。不同客户端的 HTTP 配置字段可能略有差异。": "사용 전에 <AI_CANVAS_IP>를 AI Canvas를 실행하는 컴퓨터의 LAN IP로 바꾸세요. HTTP 설정 필드는 클라이언트마다 다를 수 있습니다.",
	连接环境要求: "연결 환경 요구사항",
	"AI Canvas 桌面端": "AI Canvas 데스크톱 앱",
	"软件需保持运行，并开启上方“本地控制会话”。": "앱을 계속 실행하고 위의 \"로컬 제어 세션\"을 시작하세요.",
