	"支持 MCP 的客户端": "MCP 지원 클라이언트",
	"客户端需支持 stdio 类型的 MCP 服务配置，例如 Claude Desktop、Cursor 或 Codex。": "클라이언트는 Claude Desktop, Cursor, Codex 등 stdio 유형의 MCP 서버 설정을 지원해야 합니다.",
	在同一台电脑连接: "같은 컴퓨터에서 연결",
	"控制服务只监听 127.0.0.1，不能从局域网或其他电脑远程连接。": "제어 서비스는 127.0.0.1만 수신하므로 LAN이나 다른 컴퓨터에서 원격으로 연결할 수 없습니다.",
	"首次连接：": "최초 연결: ",
	"开启会话 → 复制上方配置 → 粘贴到客户端的 MCP 配置中 → 完全重启客户端。": "세션 시작 → 위 설정 복사 → 클라이언트 MCP 설정에 붙여넣기 → 클라이언트 완전 재시작.",
	"修改端口或重置令牌后，需要重新复制配置并重启客户端。调用联网、云端模型或本地模型功能时，还需提前配置对应的网络、API Key 或模型环境。": "포트 변경 또는 토큰 재설정 후에는 설정을 다시 복사하고 클라이언트를 재시작해야 합니다. 웹, 클라우드 모델, 로컬 모델 기능을 사용하려면 해당 네트워크, API 키 또는 모델 환경을 미리 구성해야 합니다.",
	"未找到本地 MCP 适配器脚本。": "로컬 MCP 어댑터 스크립트를 찾지 못했습니다.",
	"软件需保持运行，并开启上方“远程控制会话”。": "앱을 계속 실행하고 위의 \"원격 제어 세션\"을 시작하세요.",
	可达的局域网地址: "접근 가능한 LAN 주소",
	"客户端需能访问这台电脑的局域网 IP 和所选端口；Docker 可使用 host.docker.internal。": "클라이언트는 이 컴퓨터의 LAN IP와 선택한 포트에 접근할 수 있어야 합니다. Docker는 host.docker.internal을 사용할 수 있습니다.",
	"支持 Streamable HTTP": "Streamable HTTP 지원",
	"客户端需支持 Streamable HTTP MCP，并允许配置 Authorization 请求头。": "클라이언트는 Streamable HTTP MCP를 지원하고 Authorization 헤더를 설정할 수 있어야 합니다.",
	"Bearer Token 鉴权": "Bearer 토큰 인증",
	"每次请求都必须携带本机凭据存储中的 256 位令牌。": "모든 요청에는 로컬 자격 증명 저장소의 256비트 토큰이 포함되어야 합니다.",
	"确认开启远程 MCP": "원격 MCP 시작 확인",
	"确认暴露远程 MCP 服务": "원격 MCP 서비스 노출 확인",
	"服务将监听 0.0.0.0，局域网内能够到达该端口的设备都可以尝试连接。": "서비스는 0.0.0.0을 수신하므로 LAN 내에서 해당 포트에 도달할 수 있는 모든 장치가 연결을 시도할 수 있습니다.",
