	"提示：每个中转站提供的模型和参数规则都不一样，从接口拉取下来的模型，不一定能直接拿来用。不同中转站对同一个模型的名字、传入图片、尺寸等参数往往不同，直接使用可能会报错。请先查看你所用中转站的官方文档，把对应的参数改成文档里的值。如果你不会改，可以这样做：直接把中转站的文档发给对话助手，或者开启智能体并接入 MCP，让助手照着文档帮你添加和配置。": "팁: 각 중계 공급자는 모델과 매개변수 규칙이 다르며, API에서 가져온 모델이 그대로 동작한다는 보장이 없습니다. 같은 모델이라도 중계사마다 이름, 이미지 입력, 크기 등의 매개변수가 달라 직접 사용하면 오류가 날 수 있습니다. 사용 중인 중계사의 공식 문서를 확인하고 매개변수를 문서 값에 맞게 수정하세요. 수정이 어렵다면 중계사 문서를 대화 어시스턴트에게 보내거나 에이전트를 활성화해 MCP를 연결하여 문서에 따라 추가·설정하게 하세요.",
